 c:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12a8 8 0 1 1 3.3 6.5L3.5 20l1.3-3.6A8 8 0 0 1 4 12z" stroke-linejoin="round"/></svg>',
