let famDraft=null,famEdit=false;
function showFamille(edit){
 famEdit=!!(edit&&G);famDraft=famEdit?G.family.map(f=>({id:f.id,role:f.role,name:f.name,trait:f.trait,av:f.av})):clone(DEFAULT_FAM).map(f=>({...f,seed:Math.floor(Math.random()*1e9)}));
 closeSheet();$('atelier').hidden=true;$('game').hidden=true;$('gFabs').hidden=true;document.body.classList.remove('playing');$('famille').hidden=false;
 $('famGo').textContent=famEdit?'Enregistrer et revenir au jeu':'Commencer la partie';drawFam();window.scrollTo(0,0);
}
function drawFam(){
 $('famNom').textContent=me().nom?`Toute la famille porte ton nom : ${me().nom}.`:'Ajoute un nom de famille dans l\'atelier pour que toute la famille le porte.';
 $('famList').innerHTML=famDraft.map((f,i)=>`<div class="fam-card" data-i="${i}"><button class="fam-av" type="button" data-look="${i}" aria-label="Modifier l'apparence de ${esc(f.name)}">${render(f.av||famAvatar(f.role,f.seed??hash(f.name+f.role+i)),AVB,uid(),true)}</button>
 <div class="fam-fields"><div class="field"><label for="fr${i}">Rôle</label><select id="fr${i}" data-k="role">${ROLES.map(r=>`<option ${r===f.role?'selected':''}>${r}</option>`).join('')}</select></div>
 <div class="field"><label for="fn${i}">Prénom</label><input id="fn${i}" data-k="name" maxlength="20" value="${esc(f.name)}"></div>${me().nom?`<div class="field"><span class="lbl">Nom</span><span class="famname">${esc(me().nom)}</span></div>`:''}
 <div class="field"><label for="ft${i}">Caractère</label><select id="ft${i}" data-k="trait">${TRAITS.map(r=>`<option ${r===f.trait?'selected':''}>${r}</option>`).join('')}</select></div></div>
 <div class="fam-btns"><button class="btn small fam-dice" type="button" data-fdice="${i}" aria-label="Tirer au sort l'apparence de ${esc(f.name)}" title="Apparence au hasard"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4.5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="8" cy="8" r="1.6" fill="currentColor"/><circle cx="16" cy="8" r="1.6" fill="currentColor"/><circle cx="12" cy="12" r="1.6" fill="currentColor"/><circle cx="8" cy="16" r="1.6" fill="currentColor"/><circle cx="16" cy="16" r="1.6" fill="currentColor"/></svg></button><button class="btn small" type="button" data-look="${i}">Apparence</button><button class="btn small" type="button" data-rm="${i}" aria-label="Retirer ${esc(f.name)}">Retirer</button></div></div>`).join('')||'<p class="hint">Aucun membre pour l\'instant. Ajoute au moins une personne qui vit avec toi.</p>';
}
$('famList').addEventListener('change',e=>{const c=e.target.closest('.fam-card');if(!c)return;famDraft[+c.dataset.i][e.target.dataset.k]=e.target.value;if(e.target.dataset.k!=='name')drawFam()});
$('famList').addEventListener('input',e=>{const c=e.target.closest('.fam-card');if(!c||e.target.dataset.k!=='name')return;famDraft[+c.dataset.i].name=e.target.value});
$('famList').addEventListener('click',e=>{const fd=e.target.closest('[data-fdice]');if(fd){const f=famDraft[+fd.dataset.fdice];f.av=null;f.seed=Math.floor(Math.random()*1e9);drawFam();return}const lk=e.target.closest('[data-look]');if(lk){editFamLook(+lk.dataset.look);return}const b=e.target.closest('[data-rm]');if(!b)return;famDraft.splice(+b.dataset.rm,1);drawFam()});
$('famDiceAll').onclick=()=>{famDraft.forEach(f=>{f.av=null;f.seed=Math.floor(Math.random()*1e9)});drawFam();toast('Nouvelle famille tirée au sort')};
$('famAdd').onclick=()=>{if(famDraft.length>=6){toast('6 membres maximum');return}famDraft.push({role:pickR(['Grande sœur','Grand frère','Grand-mère','Tante']),name:pickR(['Maryse','Josué','Ketty','Rudy','Léonie','Fabrice']),trait:pickR(TRAITS),seed:Math.floor(Math.random()*1e9)});drawFam()};
$('famBack').onclick=()=>{$('famille').hidden=true;if(famEdit)showGame();else showAtelier()};
$('famGo').onclick=()=>{
 try{localStorage.setItem(KEY,JSON.stringify(me()))}catch(e){}
 famDraft.forEach(f=>{f.name=(f.name||'').trim()||f.role});
 if(famEdit){G.family=famDraft.map((f,i)=>{const old=G.family.find(x=>x.id===f.id);const id=old?old.id:'fam'+Date.now()+i;if(G.famRel[id]==null)G.famRel[id]=65;return{role:f.role,name:f.name,trait:f.trait,id,av:f.av||famAvatar(f.role,f.seed??hash(f.name+f.role+i))}});saveG();showGame();return}
 G=newGame(famDraft);planPosts();pickRival();G.wsnap=weekSnap();
 G.phaseKey=phase().key;G.lastPhase=phase();
 if(G.rel.ines&&G.rel.ines.ami>=60)pushMsg('ines','them',`Coucou ! C'est toi ${me().sexe==='f'?'la nouvelle':me().sexe==='m'?'le nouveau':'le ou la nouvelle'} ? Bienvenue au lycée ✨ si t'as besoin de quoi que ce soit, demande-moi 🥰`);
 if(G.family[0])pushMsg(G.family[0].id,'them',`Bonne rentrée ${me().name||''} ❤️ Les cours commencent à 8h, ne sois pas en retard !`);
 note('Bienvenue au lycée ! Les cours commencent à 8h.');saveG();showGame();feteDay();saveG();
};
function showGame(){musMode('jeu');
 if(!G){showFamille(false);return}
 {const l=$('loader');if(l&&l.hidden&&l.querySelector){loadShow('Chargement du lycée…');setTimeout(()=>loadHide(),0)}}
 $('atelier').hidden=true;$('famille').hidden=true;$('game').hidden=false;document.body.classList.add('playing');
 if(!G.phaseKey){G.phaseKey=phase().key;G.lastPhase=phase()}
 view='home';drawGame();window.scrollTo(0,0);musAuto();
}
function setAtelierMode(){const fm=!!editFam,f=fm&&famDraft[editFam.i];
 $('atTitle').textContent=fm?`Apparence de ${state.name||f.role}`:'Création de novas';
 $('atSub').textContent=fm?`${f.role} · visage, cheveux et tenue.`:'Crée le nova qui rentrera au lycée.';
 $('idBlock').hidden=fm;$('bSave').hidden=fm;$('bPlay').hidden=fm;$('codeBox').hidden=fm;$('bFamDone').hidden=!fm;$('nomLbl').textContent=fm?'Prénom':'Prénom du nova';$('nomFamBox').hidden=fm;}
function editFamLook(i){withLoader('Création de novas…',()=>editFamLook0(i))}
function editFamLook0(i){
 const f=famDraft[i];editFam={i,saved:state};
 state=normalize(f.av||famAvatar(f.role,f.seed??hash(f.name+f.role+i)));state.name=f.name;
 $('famille').hidden=true;$('atelier').hidden=false;tab=0;sub=0;pview='portrait';setAtelierMode();drawTabs();drawSubs();nom.value=state.name;$('nomFam').value=state.nom||'';refresh();window.scrollTo(0,0);
}
$('bFamDone').onclick=()=>{const f=famDraft[editFam.i],av=clone(state);f.name=(state.name||'').trim()||f.role;delete av.name;f.av=av;
 state=editFam.saved;editFam=null;setAtelierMode();nom.value=state.name;$('nomFam').value=state.nom||'';$('atelier').hidden=true;$('famille').hidden=false;drawFam();window.scrollTo(0,0);toast(`Apparence de ${f.name} enregistrée`)};
function restartGame(){$('game').hidden=true;$('gFabs').hidden=true;document.body.classList.remove('playing');closeSheet();G=null;try{localStorage.removeItem(GKEY)}catch(e){}cloudPush();if(typeof musStop==='function')musStop();toast('Nouvelle partie : recrée ta famille puis commence');showFamille(false)}
function askRestart(){openSheet(`<div class="who"><div style="flex:1;min-width:0"><h2>Recommencer la partie ?</h2><p class="muted" style="margin:2px 0 0">Ta progression, tes notes, tes relations et tes messages seront effacés. Ton avatar est conservé.</p></div><button class="gbtn ghost" type="button" data-close aria-label="Fermer">✕</button></div><div class="row"><button class="gbtn ghost" type="button" data-close>Annuler</button><button class="gbtn danger" type="button" id="gRestartOk">Oui, recommencer</button></div>`)}
/* écran de chargement : reste affiché jusqu'à ce que les images visibles et les portraits soient prêts (6 s au plus) */
let ldT0=Date.now()-(window.performance?performance.now():0);
function loadShow(t){const l=$('loader');if(!l)return;l.querySelector('.ld-t').textContent=t||'Chargement…';l.hidden=false;l.classList.remove('out');ldT0=Date.now()}
const LD_IMG={};
/* images des SVG (coiffures, chaussures, yeux…) : préchargées pour savoir quand elles sont prêtes */
function svgImgsReady(){let ok=true;document.querySelectorAll('svg image').forEach(el=>{const u=el.getAttribute('href')||el.getAttribute('xlink:href');if(!u||u.startsWith('data:')||el.closest('[hidden]'))return;
 let im=LD_IMG[u];if(!im){im=LD_IMG[u]=new Image();im.src=u}if(!im.complete)ok=false});return ok}
function loadHide(min){const l=$('loader');if(!l||!l.classList||l.hidden)return;const end=Date.now()+15000;let okSince=0;
 const ready=()=>[...document.images].filter(i=>i.offsetParent&&!i.closest('#loader')).every(i=>i.complete)&&!bakeQ.length&&!bakeBusy&&!HT_PEND&&svgImgsReady();
 const fin=()=>{if(l.classList.contains('out'))return;l.classList.add('out');setTimeout(()=>{l.hidden=true;l.classList.remove('out')},320)};
 /* tout doit être prêt pendant 0,6 s d'affilée (le temps que les coiffures recolorées s'affichent) */
 const chk=()=>{const now=Date.now();if(ready()){okSince=okSince||now}else okSince=0;
  if(now<end&&(now-ldT0<(min||1500)||!okSince||now-okSince<600)){setTimeout(chk,120);return}fin()};
 (document.fonts&&document.fonts.ready||Promise.resolve()).then(chk,chk)}
function withLoader(t,fn){const l=$('loader');if(!l||!l.querySelector||typeof requestAnimationFrame!=='function'){fn();return}loadShow(t);requestAnimationFrame(()=>setTimeout(()=>{try{fn()}finally{loadHide()}},40))}
function showAtelier(){withLoader('Création de novas…',showAtelier0)}
function showAtelier0(){
 closeSheet();musMode('atelier');$('game').hidden=true;$('gFabs').hidden=true;$('famille').hidden=true;document.body.classList.remove('playing');$('atelier').hidden=false;
 $('bPlay').textContent=G?'Reprendre la partie':'Suivant : ma famille';$('bRestart').hidden=!G;refresh();window.scrollTo(0,0);
}
$('bPlay').onclick=()=>{try{localStorage.setItem(KEY,JSON.stringify(me()))}catch(e){}if(G)showGame();else showFamille(false)};

nom.value=me().name;$('nomFam').value=me().nom||'';drawTabs();drawSubs();refresh();
$('bPlay').textContent=G?'Reprendre la partie':'Suivant : ma famille';$('bRestart').hidden=!G;
$('bRestart').onclick=askRestart;
/* cercle des couleurs au-dessus du nova : toutes les couleurs du personnage au même endroit */
/* couleurs de l'onglet en cours (visage → peau, cheveux → couleur, haut, bas, chaussures…) */
function colRows(){const T=TABS[tab],S=T.subs[sub]||{},jean=typeof JEAN_ART!=='undefined'&&JEAN_ART[state.bottom];
 if(T.label==='Visage'||T.label==='Corps')return [['skin','Peau',SKIN]];
 if(T.label==='Yeux')return [['iris','Iris',IRIS],['browColor','Sourcils',BROWC]];
 if(T.label==='Cheveux')return [['hairColor','Cheveux',HAIR]];
 if(T.label==='Fond')return [['bgColor','Fond',BGC]];
 const W={top:[['topColor','Haut',CLOTH]],bottom:jean?[]:[['bottomColor','Bas',BOTC]],dress:[['dressColor','Robe',CLOTH]],jacket:[['jacketColor','Veste',CLOTH]],shoes:[['shoesColor','Chaussures',SHOEC]]}[S.wear];return W||[]}
function colPopDraw(){const P=$('colPop'),rows=colRows();
 P.innerHTML=`<div class="colpop-h"><b>Couleurs</b><button type="button" class="linkbtn" data-colclose>Fermer</button></div>`+rows.map(([k,l,C])=>`<div class="colrow"><span>${l}</span><div class="colsw">${C.map(c=>`<button type="button" class="sw${state[k]===c?' on':''}" style="background:${c}" data-colk="${k}" data-colv="${c}" aria-label="${l} ${c}"></button>`).join('')}</div></div>`).join('')}
$('colPop').addEventListener('click',e=>{const b=e.target.closest('[data-colk]');if(b){state[b.dataset.colk]=b.dataset.colv;refresh();colPopDraw();return}if(e.target.closest('[data-colclose]'))$('colPop').hidden=true});
$('bAtMus').onclick=e=>{e.stopPropagation();musMode('atelier');const on=!MUS.on;try{localStorage.setItem(MUSKEY,on?'on':'off')}catch(x){}on?musStart():musStop();drawMusicBtn()};
drawMusicBtn();

if(G)showGame();
loadHide(2500);
